    def decorator(func):
        cache = {}
        freq = defaultdict(set)
        hits = defaultdict(int)

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items()))
            if key not in cache:
                cache[key] = func(*args, **kwargs)
                freq[key].add(len(cache))
