def format(sql, params):
    # Check if the input is a string or bytes
    if isinstance(sql, str):
        sql = sql.encode()

    # Check if the input is a dictionary or a list
    if isinstance(params, dict):
        params = list(params.items())

    # Convert the in-style parameters to out-style parameters
    out_params = []
    for i, param in enumerate(params):
        if isinstance(param, tuple):
            out_params.append((f"@{i}", param[1]))
        else:
            out_params.append((f"@{i}", param))

    # Replace the in-style parameters with out-style parameters in the SQL query
    for i, param in enumerate(out_params):
        sql = sql.replace(f"@{i}", param[0])

    return (sql, out_params)

