    import subprocess

    if isinstance(commands, str):
        commands = [commands]

    if env is None:
        env = os.environ.copy()

    for command in commands:
        if verbose:
            print(f"Running command: {command}")

        process = subprocess.Popen(command, shell=True, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
